import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"技术路线与演进节奏","description":"","frontmatter":{"title":"技术路线与演进节奏","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/technical-roadmap.md","filePath":"frontend/decisions/technical-roadmap.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/technical-roadmap.md"};function l(o,t,h,n,c,s){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="技术路线与演进节奏" tabindex="-1">技术路线与演进节奏 <a class="header-anchor" href="#技术路线与演进节奏" aria-label="Permalink to &quot;技术路线与演进节奏&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>技术路线不是未来工具名称的愿望清单，而是把业务变化、能力缺口、架构依赖和停止条件组织成可调整的演进顺序。它需要回答“为什么现在做”“先解决哪种风险”“什么证据允许进入下一阶段”，同时保留改变方向的空间。</p><h2 id="_1-路线规划的对象" tabindex="-1">1. 路线规划的对象 <a class="header-anchor" href="#_1-路线规划的对象" aria-label="Permalink to &quot;1. 路线规划的对象&quot;">​</a></h2><h3 id="_1-1-从能力缺口出发" tabindex="-1">1.1 从能力缺口出发 <a class="header-anchor" href="#_1-1-从能力缺口出发" aria-label="Permalink to &quot;1.1 从能力缺口出发&quot;">​</a></h3><p>“今年升级 Vite、明年上微前端”只描述手段。更稳定的路线应先描述能力：缩短发布反馈、降低跨模块耦合、建立统一身份边界、让遗留页面能够分批退休。工具选择可以随证据改变，能力目标不应轻易漂移。</p><h3 id="_1-2-区分承诺、选择权和探索" tabindex="-1">1.2 区分承诺、选择权和探索 <a class="header-anchor" href="#_1-2-区分承诺、选择权和探索" aria-label="Permalink to &quot;1.2 区分承诺、选择权和探索&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>含义</th><th>管理方式</th></tr></thead><tbody><tr><td>承诺</td><td>已有明确业务窗口和资源</td><td>进入交付计划并设置验收门槛</td></tr><tr><td>选择权</td><td>可能需要，先保留低成本入口</td><td>控制耦合，不提前建设完整平台</td></tr><tr><td>探索</td><td>关键未知量尚未验证</td><td>时间盒实验，不承诺生产落地</td></tr></tbody></table><p>把探索写成承诺会制造虚假确定性；把所有事项都写成探索，则无法协调依赖和资源。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><p>路线必须纳入业务冻结期、合同到期、框架维护终止、安全整改期限、团队容量和并行项目上限。评价一项演进工作时，至少比较：业务风险降低、后续工作的解锁程度、持续维护成本、迁移可逆性和验证周期。</p><p>安全漏洞修复和停止维护版本的退出可能是硬期限，不应被普通功能收益评分推后。</p><h2 id="_3-候选演进方式" tabindex="-1">3. 候选演进方式 <a class="header-anchor" href="#_3-候选演进方式" aria-label="Permalink to &quot;3. 候选演进方式&quot;">​</a></h2><h3 id="_3-1-大版本集中迁移" tabindex="-1">3.1 大版本集中迁移 <a class="header-anchor" href="#_3-1-大版本集中迁移" aria-label="Permalink to &quot;3.1 大版本集中迁移&quot;">​</a></h3><p>适合范围清晰、自动化覆盖充足、短期双轨成本高且能获得完整业务窗口的系统。优点是目标状态统一；风险是反馈晚、并行冲突大、失败时回退困难。</p><h3 id="_3-2-按业务切片渐进演进" tabindex="-1">3.2 按业务切片渐进演进 <a class="header-anchor" href="#_3-2-按业务切片渐进演进" aria-label="Permalink to &quot;3.2 按业务切片渐进演进&quot;">​</a></h3><p>以路由、领域模块或用户旅程为单位逐步替换，适合大型在线系统。它能持续获得真实反馈，但需要临时兼容层、双轨监控和清晰的退休标准。</p><h3 id="_3-3-维持与隔离" tabindex="-1">3.3 维持与隔离 <a class="header-anchor" href="#_3-3-维持与隔离" aria-label="Permalink to &quot;3.3 维持与隔离&quot;">​</a></h3><p>当系统稳定、变更少且迁移收益不足时，可以冻结旧模块，只修复高风险问题，并通过 API 或外壳隔离。维持现状必须有责任人、支持期限和重新评估条件，不能成为无人决策的永久状态。</p><h2 id="_4-关键依赖与排序" tabindex="-1">4. 关键依赖与排序 <a class="header-anchor" href="#_4-关键依赖与排序" aria-label="Permalink to &quot;4. 关键依赖与排序&quot;">​</a></h2><p>排序应遵循“先降低不确定性，再建立基础能力，最后扩大迁移范围”：</p><ol><li>先建立可观测基线和回归测试，否则无法判断迁移是否改善；</li><li>再抽离稳定的领域契约和部署边界，减少新旧实现互相渗透；</li><li>选择一个低风险但能覆盖完整链路的切片试点；</li><li>达到成功阈值后批量迁移，并持续删除兼容层；</li><li>达不到阈值时停止扩张，修正方案或撤销试点。</li></ol><p>依赖关系比日历日期更重要。没有监控和回滚能力时，不应仅因为季度计划而开始大规模替换。</p><h2 id="_5-场景化推荐路线" tabindex="-1">5. 场景化推荐路线 <a class="header-anchor" href="#_5-场景化推荐路线" aria-label="Permalink to &quot;5. 场景化推荐路线&quot;">​</a></h2><p>案例：一个运行六年的 Vue 2 运营系统有 46 个路由、12 名维护者，每周发布；旧组件库停止新增功能，但系统仍承担核心订单处理。目标是在 18 个月内迁移到 Vue 3，同时不能暂停业务迭代。</p><p>推荐采用按领域切片的渐进演进：</p><table tabindex="0"><thead><tr><th>阶段</th><th>时间盒</th><th>目标与门槛</th></tr></thead><tbody><tr><td>基线</td><td>0 至 2 个月</td><td>建立关键旅程 E2E、错误率和交付周期基线；路由清单有负责人</td></tr><tr><td>试点</td><td>3 至 5 个月</td><td>迁移“导出中心”完整链路；错误率不高于旧版，交付周期不增加超过 15%</td></tr><tr><td>扩展</td><td>6 至 14 个月</td><td>按订单、库存、结算三个领域迁移；每批删除对应旧代码和兼容配置</td></tr><tr><td>收尾</td><td>15 至 18 个月</td><td>关闭 Vue 2 构建链、归档回滚制品、完成依赖和监控清理</td></tr></tbody></table><p>不先建设通用微前端平台。当前只有一个产品团队，路由级双构建外壳足以支持过渡；只有独立发布冲突成为实测瓶颈时才重新评估运行时拆分。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>渐进路线降低单次切换风险，并允许业务继续交付，但会暂时存在两套构建、组件和排障路径。路线预算必须覆盖兼容层维护、双轨测试和旧代码删除，不能只估算新页面开发。</p><p>每个阶段都要产生可删除的旧资产。若新系统不断增加而旧系统不减少，团队不是在迁移，而是在永久维护双倍复杂度。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>不要把所有团队愿望都放进路线；没有目标、负责人和触发条件的事项应留在候选池。</li><li>不要按厂商版本发布时间排路线，而忽略业务冻结和依赖关系。</li><li>不要用三年远期日期制造确定性；远期内容应表达方向和选择权。</li><li>不要在缺少真实基线时承诺“性能提升 50%”或“效率翻倍”。</li></ul><h2 id="_8-填写完成的路线记录" tabindex="-1">8. 填写完成的路线记录 <a class="header-anchor" href="#_8-填写完成的路线记录" aria-label="Permalink to &quot;8. 填写完成的路线记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>业务目标</td><td>保持每周交付，同时在 18 个月内退出停止扩展的 Vue 2 栈</td></tr><tr><td>硬约束</td><td>订单关键旅程不可停机；每阶段最多投入 4 人；年末冻结两个月</td></tr><tr><td>路线方式</td><td>领域切片渐进迁移</td></tr><tr><td>当前承诺</td><td>基线建设和导出中心试点</td></tr><tr><td>保留选择权</td><td>若团队拆分且发布冲突持续，再评估微前端</td></tr><tr><td>明确不做</td><td>试点通过前不统一重写全部组件、不更换服务端 API 风格</td></tr><tr><td>成功指标</td><td>旧路由数量、双轨缺陷率、交付周期、兼容层数量均按月跟踪</td></tr><tr><td>停止条件</td><td>试点错误率高于旧版 20%，或交付周期连续两月恶化超过 15%</td></tr></tbody></table><h2 id="_9-复查节奏" tabindex="-1">9. 复查节奏 <a class="header-anchor" href="#_9-复查节奏" aria-label="Permalink to &quot;9. 复查节奏&quot;">​</a></h2><p>路线每月检查执行数据、每季度重新排序，不在每次复查时推翻长期目标。出现监管期限变化、核心依赖停止支持、团队容量减少 30%、试点门槛失败或业务战略改变时，应立即重新规划。</p><p>路线的价值不在于预测未来，而在于让下一步依赖什么证据、承担什么代价以及何时停止变得明确。</p>',38)])])}const b=a(i,[["render",l]]);export{_ as __pageData,b as default};
